1001	\begin{lemma}[Combined line measurements]
1002		\label{lem:qld-xz-lines}
1003		\lean{MIPStarRE.QPBT.CombinedLinesWitness}
1004		\lean{MIPStarRE.QPBT.exists_combinedLinesWitness}
1005		\notready
1006		\uses{lem:qld-4-10, def:line, def:line-point-dist, def:consistency,
1007			def:bracket, def:expanded-state, def:symmetric-equivalents,
1008			def:ideg-deg-polynomials}
1009		There exists a function $\delta_P(\eps,m,d,q) = \poly(\eps, md/q)$, the
1010		two-variable polynomial error read in the corrected sum sense of
1011		\cite{gap:qpbt_pasting-product-error}, that is, a bound
1012		$C\bigl(\eps^{r} + (md/q)^{s}\bigr)$ with $C \ge 1$ and $r, s > 0$ on the
1013		closed nonnegative quadrant rather than the literal product form of the
1014		shorthand, such that the following holds. For
1015		$\hilb \in \{\hilb_{\mathsf{A}}, \hilb_{\mathsf{B}}\}$ and every pair of
1016		lines $\ell_X$ and $\ell_Z$ in $\F_q^m$ there exists a POVM
1017		$\{T^{\ell_X,\ell_Z}_{f_X,f_Z}\}$ acting on $\hilb \ot (\C^q)^{\ot M}$,
1018		with answers consisting of pairs of polynomials
1019		$(f_X, f_Z) \in \deg_{md}(\ell_X) \times \deg_{md}(\ell_Z)$, such that on
1020		average over pairs $(\ell_X, x)$ and $(\ell_Z, z)$ independently sampled
1021		from the line-point distribution
1022		(Definition~\ref{def:line-point-dist}),
1023		\[
1024			\big(T^{\ell_X,\ell_Z}
1025			_{[\mathrm{eval}_x(\cdot)=a,\ \mathrm{eval}_z(\cdot)=b]}
1026			\big)_{\mathsf{A}\mathsf{A}'}
1027			\simeq_{\delta_P}
1028			\big(\hat{Q}^{x,z}_{a,b}\big)_{\mathsf{B}\mathsf{A}''}\,,
1029		\]
1030		as well as all symmetric equivalents of this approximation. Moreover, if
1031		$\ell_W$ is axis-parallel, then $f_W \in \deg_{d}(\ell_W)$.
1032	\end{lemma}
1033	\begin{proof}
1034		\uses{def:expanded-line-measurement, lem:qld-4-10, fact:add-a-proj,
1035			lem:cool-closeness-fact, lem:qld-comm-line-cons, fact:agreement,
1036			fact:data-processing, lem:pasting, lem:schwartz-zippel-total-degree,
1037			def:symmetric-equivalents, def:concrete-paired-line-measurement,
1038			lem:concrete-paired-line-degree-support}
1039		Define, for all lines $\ell_X, \ell_Z$ and
1040		$(f_X, f_Z) \in \deg_{md}(\ell_X) \times \deg_{md}(\ell_Z)$, the sandwich
1041		operator
1042		$T^{\ell_X,\ell_Z}_{f_X,f_Z}
1043		= \hat{M}^{(\mathrm{Line},X),\ell_X}_{f_X}
1044		\hat{M}^{(\mathrm{Line},Z),\ell_Z}_{f_Z}
1045		\hat{M}^{(\mathrm{Line},X),\ell_X}_{f_X}$,
1046		which forms a valid POVM; since the lines measurements come from a valid
1047		strategy for the low-degree test, on an axis-parallel line $\ell_W$ the
1048		outcome $f_W$ lies in $\deg_d(\ell_W)$, and this property is inherited by
1049		$T$. As intermediate consistency relations, write
1050		$\hat{Q}^{x,z}_{a,\bullet} = \sum_b \hat{Q}^{x,z}_{a,b}$ and
1051		$\hat{Q}^{x,z}_{\bullet,b} = \sum_a \hat{Q}^{x,z}_{a,b}$ for the two
1052		marginals of the combined point measurement of
1053		Lemma~\ref{lem:qld-4-10}. Applying
1054		Lemma~\ref{fact:add-a-proj} to \eqref{eq:qld-q-cons-m-hat-zx} and then
1055		Lemma~\ref{lem:cool-closeness-fact} gives, on average over uniform
1056		$x, z$,
1057		$(\hat{Q}^{x,z}_{a,\bullet})_{\mathsf{A}\mathsf{A}'}
1058		\approx_\delta
1059		\sum_b (\hat{Q}^{x,z}_{a,b})_{\mathsf{A}\mathsf{A}'}
1060		(\hat{M}^{(\mathrm{Point},Z),z}_{b})_{\mathsf{B}\mathsf{A}''}$,
1061		and a direct norm computation from this display and
1062		\eqref{eq:qld-q-cons-m-hat-zx} yields the marginal consistencies
1063		$(\hat{Q}^{x,z}_{a,\bullet})_{\mathsf{A}\mathsf{A}'} \approx_{\delta_Q}
1064		(\hat{M}^{(\mathrm{Point},X),x}_{a})_{\mathsf{B}\mathsf{A}''}$ and
1065		$(\hat{Q}^{x,z}_{\bullet,b})_{\mathsf{A}\mathsf{A}'} \approx_{\delta_Q}
1066		(\hat{M}^{(\mathrm{Point},Z),z}_{b})_{\mathsf{B}\mathsf{A}''}$.
1067		From items 1 and 3 of Lemma~\ref{lem:qld-comm-line-cons}, converting
1068		between $\approx$ and $\simeq$ with Lemma~\ref{fact:agreement} and
1069		summing outcomes with Lemma~\ref{fact:data-processing}, the lines
1070		measurements are consistent with the points measurements, and combining
1071		with the marginal consistencies gives, on average over the line-point
1072		distribution,
1073		$(\hat{Q}^{x,z}_{a,\bullet})_{\mathsf{A}\mathsf{A}'} \simeq_{\delta_Q}
1074		(\hat{M}^{(\mathrm{Line},X),\ell_X}
1075		_{[\mathrm{eval}_x(\cdot)=a]})_{\mathsf{B}\mathsf{A}''}$
1076		together with the analogous relation for $Z$. The conclusion now follows
1077		from the pasting lemma (Lemma~\ref{lem:pasting}) applied with
1078		$\hat{Q}^{x,z}_{a,b}$ in the role of the combined measurement,
1079		$\hat{M}^{(\mathrm{Line},X),\ell_X}$ and
1080		$\hat{M}^{(\mathrm{Line},Z),\ell_Z}$ in the roles of the two factor
1081		measurements, $T^{\ell_X,\ell_Z}$ in the role of the pasted measurement,
1082		$\delta := \delta_Q$, and $\eta := md/q$, the last justified by the
1083		Schwartz--Zippel bound (Lemma~\ref{lem:schwartz-zippel-total-degree})
1084		applied to the polynomials $f_X, f_Z$ of total degree at most $md$; the
1085		two hypotheses of the pasting lemma are supplied by the preceding display
1086		and by \eqref{eq:qld-q-self-cons}, and the distribution over
1087		$(\ell_X, \ell_Z)$ is that of two independent uniformly random lines. The
1088		register-exchanged comparison \eqref{eq:pasting-1-sym} is supplied by the
1089		symmetric equivalents of that preceding display, which
1090		Lemma~\ref{lem:qld-4-10} establishes for all of its approximations.
1091		This gives the stated relation with $\delta_P$ equal to the pasting
1092		error, a $\poly(\eps, md/q)$ function, and the identical argument with
1093		the registers modified gives all symmetric equivalents.
1094	\end{proof}
