1201	\begin{lemma}[Formalization support: discarded zero directions]
1202		\label{lem:qld-zero-direction-mass}
1203		\lean{MIPStarRE.QPBT.dLinePointDist_zero_direction_mass_le}
1204		\lean{MIPStarRE.QPBT.linePointDist_zero_direction_mass_le}
